function getLocalWorkforceSnapshot() {
	try {
		if (typeof localStorage !== "undefined") {
			const raw = localStorage.getItem(LOCAL_WORKFORCE_STORAGE_KEY);
			if (raw) {
				const parsed = JSON.parse(raw);
				if (parsed && parsed.company && Array.isArray(parsed.employees) && Array.isArray(parsed.logs)) return parsed;
			}
		}
	} catch {}
	return buildDefaultSnapshot();
}
