function formatLogTimestamp(iso, language) {
	const d = new Date(iso);
	if (Number.isNaN(d.getTime())) return iso;
	try {
		return new Intl.DateTimeFormat(language === "ar" ? "ar-EG" : "en-GB", {
			dateStyle: "medium",
			timeStyle: "short"
		}).format(d);
	} catch {
		return iso.replace("T", " ").slice(0, 16);
	}
}
